/* VET45 Theme 7 v3.8.0 — Task-driven Warehouse Home
 * Parent: v3.7.1
 * Goal: stop exposing the Theme 7 business-journey catalog in Product UI.
 * The integrated Kho screen becomes a production-like work center:
 *   - search inventory context
 *   - concrete work assigned/generated by current business state
 *   - two utility destinations (inventory + reports)
 *   - one explicit "Tạo thao tác" action for genuinely user-initiated flows
 * Exhaustive 17 BJ + CAP-01 access remains in the separate "Theo BJ / UIF" workbench tab.
 */
(()=>{
  const VERSION="3.8.0";
  let tasksExpanded=false;
  let manualSheetOpen=false;
  let directEntryScreen=null;

  const currentRenderAppScreen=renderAppScreen;
  const currentRenderInspector=renderInspector;

  const TASKS=[
    {flow:"UIF-02",screen:"SCR-009",title:"PN-260816-04",subtitle:"Minh Dũng · 2 dòng hàng · Cần nhận",badge:"Cần nhận",tone:"Success",icon:"cloudUpload",context:"receipt-document"},
    {flow:"UIF-05",screen:"SCR-026",title:"SO-260827-21",subtitle:"Đại lý An Phú · 2 sản phẩm · Đang lấy",badge:"Đang lấy",tone:"Info",icon:"package",context:"picking"},
    {flow:"UIF-08",screen:"SCR-044",title:"KK-0709-03",subtitle:"Kho trung tâm · 12/38 đã đếm",badge:"Đang đếm",tone:"Info",icon:"listCheck",context:"count"},
    {flow:"UIF-03",screen:"SCR-014",title:"PN-260816-02",subtitle:"An Việt · 1 dòng cần xác nhận giá nhập",badge:"Cần xác nhận",tone:"Warning",icon:"checkCircle",context:"valuation"},
    {flow:"UIF-16",screen:"SCR-078",title:"Amox 500 · L2407-A",subtitle:"Tồn kho có chênh lệch cần kiểm tra",badge:"Cần kiểm tra",tone:"Warning",icon:"search",context:"reconcile"},
  ];

  const MANUAL=[
    {flow:"UIF-02",screen:"SCR-008",title:"Nhập hàng nhanh",subtitle:"Hàng đã đến nhưng chưa có chứng từ mua",icon:"cloudUpload",context:"quick-receipt"},
    {flow:"UIF-08",screen:"SCR-043",title:"Tạo phiên kiểm kê",subtitle:"Bắt đầu một lần kiểm kê mới",icon:"listCheck",context:"new-count"},
    {flow:"UIF-09",screen:"SCR-038",title:"Chuyển tình trạng hàng",subtitle:"Tạm ngừng bán, hỏng hoặc dùng thử",icon:"shield",context:"state-change"},
    {flow:"UIF-10",screen:"SCR-040",title:"Tạo yêu cầu tiêu hủy",subtitle:"Lập yêu cầu tiêu hủy hàng có kiểm soát",icon:"xCircle",context:"disposal"},
  ];

  function params(){return new URLSearchParams(location.search);}
  function isThemeInventory(){const q=params();return document.body.dataset.workbenchMode==="theme"&&q.get("app")==="inventory";}
  function isThemeFlow(){const q=params();return document.body.dataset.workbenchMode==="theme"&&q.get("app")==="flow";}

  function bottomNav(){
    return `<nav class="t7-app-bottom-nav" aria-label="Điều hướng chính" data-theme-component="VET45BottomNavigation">
      <button type="button" disabled aria-label="Trang chủ">${icon("warehouse","icon--sm")}<span>Trang chủ</span></button>
      <button type="button" disabled aria-label="Bán hàng">${icon("package","icon--sm")}<span>Bán hàng</span></button>
      <button type="button" disabled aria-label="Đơn hàng">${icon("fileText","icon--sm")}<span>Đơn hàng</span></button>
      <button type="button" disabled aria-label="Đối tác">${icon("user","icon--sm")}<span>Đối tác</span></button>
      <button type="button" class="is-active" aria-current="page" data-theme-sidebar-route="more" aria-label="Thêm">${icon("more","icon--sm")}<span>Thêm</span></button>
    </nav>`;
  }

  function shell(body){
    return `<div class="v-page-scaffold figma-calibrated-shell t7-integrated-shell t380-warehouse-home" data-mobile-product data-product-app data-inspectable="true" data-ds-component="VPageScaffold" data-ds-profile="screen.shell.standard" data-ds-prop-title="Kho" data-ds-prop-center-title="false">
      ${statusBar()}
      <header class="app-header"><div class="app-appbar has-back" data-ds-component="VAppBar" data-ds-prop-center-title="false" data-ds-prop-actions="null" data-ds-prop-show-back-button="true">
        <button class="app-icon-button app-back-button" data-theme-app-back type="button" aria-label="Quay lại" data-ds-internal="VAppBar.leading">${icon("chevronLeft","icon--24")}</button>
        <div class="app-appbar-copy" data-ds-component="VAppBarTitle"><h3>Kho</h3></div>
      </div></header>
      <div class="app-content" data-ds-component="VPagePadding" data-ds-profile="screen.body.standard"><div class="body-stack">${body}</div></div>
      ${bottomNav()}
    </div>`;
  }

  function sectionTitle(title,meta=""){
    return `<div class="t380-section-title"><h2 data-ds-component="VText" data-ds-prop-style="Label/Default">${esc(title)}</h2>${meta?`<span data-ds-component="VText" data-ds-prop-style="Caption">${esc(meta)}</span>`:""}</div>`;
  }

  function taskRow(task){
    return ds24ListRow({
      title:task.title,
      subtitle:task.subtitle,
      leading:task.icon,
      trailing:ds24Badge(task.badge,task.tone),
      attrs:`data-theme-entry-flow="${task.flow}" data-t380-target-screen="${task.screen}" data-t380-context="${task.context}"`,
      theme:"Theme7WarehouseWorkItem",
      extraClass:"t380-work-item"
    });
  }

  function tasksBlock(){
    const visible=tasksExpanded?TASKS:TASKS.slice(0,3);
    const rows=visible.map(taskRow).join("");
    const remain=TASKS.length-3;
    const toggle=remain>0?`<button class="t380-inline-toggle" type="button" data-t380-task-toggle aria-expanded="${tasksExpanded}" data-ds-component="VButton" data-ds-prop-variant="VButtonVariant.link">${tasksExpanded?"Thu gọn":`Xem ${remain} việc khác`}${icon("chevronDown","icon--sm")}</button>`:"";
    return `<section class="t380-section t380-work-section" data-ds-component="VSection">${sectionTitle("Việc của bạn",`${TASKS.length} việc`)}<div class="ds24-list-stack t380-work-list">${rows}</div>${toggle}</section>`;
  }

  function utilities(){
    const inventory=ds24ListRow({title:"Tồn kho",subtitle:"Tra cứu số lượng, lô và khả dụng",leading:"warehouse",trailing:ds24Badge("3 cần chú ý","Warning"),attrs:'data-theme-entry-flow="UIF-01"',theme:"Theme7WarehouseUtility"});
    const report=ds24ListRow({title:"Báo cáo & thẻ kho",subtitle:"Xem tồn tại thời điểm và lịch sử biến động",leading:"history",attrs:'data-theme-entry-flow="UIF-15"',theme:"Theme7WarehouseUtility"});
    return `<section class="t380-section t380-utility-section" data-ds-component="VSection">${sectionTitle("Tra cứu")}<div class="ds24-list-stack">${inventory}${report}</div></section>`;
  }

  function manualSheet(){
    if(!manualSheetOpen)return "";
    const rows=MANUAL.map(x=>ds24ListRow({title:x.title,subtitle:x.subtitle,leading:x.icon,attrs:`data-theme-entry-flow="${x.flow}" data-t380-target-screen="${x.screen}" data-t380-context="${x.context}"`,theme:"Theme7ManualWarehouseAction"})).join("");
    return `<div class="sheet-backdrop ds24-overlay t380-manual-overlay" data-t380-manual-close><section class="ds24-select-sheet t380-manual-sheet" data-ds-component="VBottomSheet" data-figma-node="4695:6353" role="dialog" aria-modal="true" aria-label="Tạo thao tác" onclick="event.stopPropagation()"><div class="ds24-sheet__handle"></div><div class="t380-sheet-heading"><h3>Tạo thao tác</h3><p>Chỉ chọn khi bạn chủ động bắt đầu một việc mới.</p></div><div class="ds24-list-stack">${rows}</div><button class="ds24-button ds24-button--secondary" type="button" data-t380-manual-close data-ds-component="VButton">Đóng</button></section></div>`;
  }

  function search(){
    return `<div class="t380-search-wrap">${ds24Search("",'data-t380-inventory-search','Tìm sản phẩm, SKU hoặc lô')}</div>`;
  }

  function createAction(){
    return `<section class="t380-section t380-create-section" data-ds-component="VSection"><button class="ds24-button ds24-button--primary t380-create-button" type="button" data-t380-manual-open data-ds-component="VButton"><span>Tạo thao tác</span></button></section>`;
  }

  function renderWarehouseHome(){
    return shell(`${search()}${tasksBlock()}${utilities()}${createAction()}${manualSheet()}`);
  }

  function adjustDirectEntryBack(){
    if(!isThemeFlow()||!directEntryScreen||activeScreenId!==directEntryScreen)return;
    const bar=document.querySelector("#app-screen .app-appbar");
    if(!bar)return;
    bar.classList.remove("no-back");bar.classList.add("has-back");
    let back=bar.querySelector(".app-back-button");
    if(!back){bar.insertAdjacentHTML("afterbegin",`<button class="app-icon-button app-back-button" type="button" aria-label="Quay về Kho" data-ds-internal="VAppBar.leading">${icon("chevronLeft","icon--24")}</button>`);back=bar.querySelector(".app-back-button");}
    [...back.attributes].forEach(a=>{if(a.name.startsWith("data-")&&!['data-ds-internal'].includes(a.name))back.removeAttribute(a.name);});
    back.setAttribute("data-t380-back-home","");
    back.setAttribute("aria-label","Quay về Kho");
  }

  renderAppScreen=function(){
    currentRenderAppScreen();
    if(isThemeInventory()){
      const app=document.getElementById("app-screen");
      if(app)app.innerHTML=renderWarehouseHome();
      return;
    }
    adjustDirectEntryBack();
  };

  renderInspector=function(){
    currentRenderInspector();
    if(!isThemeInventory())return;
    const trace=document.getElementById("traceability");
    if(trace)trace.innerHTML=`<div class="trace-row"><span>Entry</span><strong>Thêm → Kho</strong></div><div class="trace-row"><span>IA pattern</span><strong>Task-driven work center</strong></div><div class="trace-row"><span>Product UI</span><strong>Work items + inventory search + manual actions</strong></div><div class="trace-row"><span>Exhaustive review</span><strong>Theo BJ / UIF tab</strong></div>`;
    const rationale=document.getElementById("design-rationale");
    if(rationale)rationale.textContent="Kho không còn là danh mục 17 nghiệp vụ. Màn hình ưu tiên công việc cụ thể phát sinh từ ngữ cảnh hiện hành; nghiệp vụ chủ động được gom vào một hành động Tạo thao tác. Toàn bộ BJ vẫn truy cập ở tab review riêng.";
  };

  function clickHomeRoute(){
    const btn=document.querySelector('[data-theme-sidebar-route="inventory"]');
    if(btn)btn.click();
  }

  function applyDirectContext(context){
    if(context==="receipt-document"){
      flowMode="document";selectedDocumentId="PN-260816-04";
      if(typeof resetBj02Receipt==="function")resetBj02Receipt("document");
    }else if(context==="quick-receipt"){
      flowMode="quick";
      if(typeof resetBj02Receipt==="function")resetBj02Receipt("quick");
    }else if(context==="picking"){
      io05SelectedOrderId="SO-260827-21";
      if(typeof io05ResetHandover==="function")io05ResetHandover();
      stateByScreen["SCR-026"]="READY";
    }else if(context==="count"){
      stateByScreen["SCR-044"]="READY";
    }else if(context==="new-count"){
      stateByScreen["SCR-043"]="READY";
    }else if(context==="state-change"){
      stateByScreen["SCR-038"]="READY";
    }else if(context==="disposal"){
      stateByScreen["SCR-040"]="READY";
    }
  }

  document.addEventListener("click",event=>{
    const taskToggle=event.target.closest("[data-t380-task-toggle]");
    if(taskToggle&&isThemeInventory()){
      event.preventDefault();event.stopImmediatePropagation();tasksExpanded=!tasksExpanded;render();return;
    }
    const open=event.target.closest("[data-t380-manual-open]");
    if(open&&isThemeInventory()){
      event.preventDefault();event.stopImmediatePropagation();manualSheetOpen=true;render();return;
    }
    const close=event.target.closest("[data-t380-manual-close]");
    if(close&&isThemeInventory()){
      event.preventDefault();event.stopImmediatePropagation();manualSheetOpen=false;render();return;
    }
    const direct=event.target.closest("[data-t380-target-screen]");
    if(direct){
      const target=direct.dataset.t380TargetScreen;
      const context=direct.dataset.t380Context||"";
      directEntryScreen=target;manualSheetOpen=false;applyDirectContext(context);
      activeScreenId=target;
      render();
      return;
    }
    if(event.target.closest("[data-t380-back-home]")){
      event.preventDefault();event.stopImmediatePropagation();directEntryScreen=null;clickHomeRoute();return;
    }
  },true);

  document.addEventListener("keydown",event=>{
    if(!isThemeInventory()||!event.target.matches("[data-t380-inventory-search]")||event.key!=="Enter")return;
    event.preventDefault();
    const q=event.target.value.trim();
    bj01Query=q;
    directEntryScreen="SCR-001";
    const inventory=document.querySelector('[data-theme-entry-flow="UIF-01"]');
    if(inventory)inventory.click();
  },true);

  const badge=document.querySelector(".review-meta > .review-badge:not(.review-badge--muted)");
  if(badge)badge.textContent="v3.8.0 · task-driven Warehouse Home · 17 BJ + CAP-01 behind runtime";
  if(window.__VET45_PROTOTYPE__){
    window.__VET45_PROTOTYPE__.version=VERSION;
    window.__VET45_PROTOTYPE__.scenarios=[...(window.__VET45_PROTOTYPE__.scenarios||[]),"task-driven-warehouse-home","warehouse-work-queue","manual-action-sheet","direct-context-entry"];
  }
  render();
})();
